WITH flattened_attrs AS (SELECT id, host, log_ts, latency_ms, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs) SELECT *, SUM(latency_ms) OVER (PARTITION BY host ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_latency_ms, CUME_DIST() OVER (PARTITION BY host ORDER BY latency_ms NULLS FIRST) latency_ms_cume_dist FROM flattened_attrs;
